// One build-time view of the Neurodesk application catalog. The apps.json feed
// (generated by scigetorg/apps.json) is the source of truth for which images
// exist; descriptions and OpenRecon flags come from the feed when it carries
// them, else from src/data/app-metadata.json (see scripts/update-app-metadata.mjs).
//
// Both /data/applist.json and /data/badges/<tool>.json are built from
// loadAppList(), so the application browser and the badges cannot disagree.
// Any malformed or empty feed throws, which fails the build and leaves the
// previous deployment serving.
import snapshot from '../data/app-metadata.json' with { type: 'json' };

export const APPS_JSON_URL = 'https://apps-json.scigetorg.workers.dev/neuroimaging/apps.json';

export interface AppListEntry {
	/** `<image>_<build_date>`, kept for existing consumers of /data/applist.json. */
	application: string;
	/** The apps.json tool key. */
	name: string;
	version: string;
	/** YYYYMMDD */
	build_date: string;
	categories: string[];
	doi_url?: string;
	license?: string[];
	description?: string;
	citation?: string;
	openrecon?: boolean;
}

export interface ToolMetadata {
	description?: string;
	openrecon?: boolean;
}

interface FeedApp {
	image: string;
	version: string;
	doi?: string;
	license?: string[];
	show_in_applist?: boolean;
}

interface FeedTool extends ToolMetadata {
	citation?: string;
	apps: Record<string, FeedApp>;
	categories: string[];
}

export type AppsFeed = Record<string, FeedTool>;

function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function isStringArray(value: unknown): value is string[] {
	return Array.isArray(value) && value.every((item) => typeof item === 'string' && item !== '');
}

function optional<T>(value: unknown, guard: (value: unknown) => value is T): boolean {
	return value === undefined || guard(value);
}

const isString = (value: unknown): value is string => typeof value === 'string';
const isBoolean = (value: unknown): value is boolean => typeof value === 'boolean';

export function parseAppsFeed(data: unknown): AppsFeed {
	if (!isRecord(data)) throw new Error('apps.json must be an object of tools');
	for (const [tool, entry] of Object.entries(data)) {
		if (!isRecord(entry) || !isRecord(entry.apps) || !isStringArray(entry.categories)) {
			throw new Error(`apps.json tool ${tool} needs an apps object and a categories list`);
		}
		if (
			!optional(entry.description, isString) ||
			!optional(entry.citation, isString) ||
			!optional(entry.openrecon, isBoolean)
		) {
			throw new Error(`apps.json tool ${tool} has an invalid description, citation or openrecon flag`);
		}
		for (const [name, app] of Object.entries(entry.apps)) {
			if (
				!isRecord(app) ||
				typeof app.image !== 'string' ||
				!app.image.startsWith(`${tool}_`) ||
				app.image.length === tool.length + 1 ||
				typeof app.version !== 'string' ||
				!/^\d{8}$/.test(app.version) ||
				!optional(app.doi, isString) ||
				!optional(app.license, isStringArray) ||
				!optional(app.show_in_applist, isBoolean)
			) {
				throw new Error(`apps.json app ${tool}/${name} is malformed`);
			}
		}
	}
	return data as AppsFeed;
}

/**
 * One entry per published image build. Launchers that share an image (for
 * example afni and sumaGUI-afni) collapse to one entry; hidden launchers are
 * dropped. Throws when nothing is left to list.
 */
export function toAppList(
	feed: AppsFeed,
	metadata: Record<string, ToolMetadata> = snapshot.tools,
): AppListEntry[] {
	const entries = new Map<string, AppListEntry>();
	for (const [tool, { apps, categories, ...feedMetadata }] of Object.entries(feed)) {
		const description = feedMetadata.description || metadata[tool]?.description;
		const openrecon = feedMetadata.openrecon ?? metadata[tool]?.openrecon;
		const citation = feedMetadata.citation?.trim();
		for (const app of Object.values(apps)) {
			if (app.show_in_applist === false) continue;
			const application = `${app.image}_${app.version}`;
			if (entries.has(application)) continue;
			// Images are `<tool>_<version>`, and the version may itself contain
			// underscores (amico_2.1.0_arm64, kul-vbg_0.61.0_23112021_beta).
			const version = app.image.slice(tool.length + 1);
			entries.set(application, {
				application,
				name: tool,
				version,
				build_date: app.version,
				categories: [...categories],
				...(app.doi ? { doi_url: app.doi } : {}),
				...(app.license?.length ? { license: [...app.license] } : {}),
				...(description ? { description } : {}),
				...(citation ? { citation } : {}),
				...(openrecon ? { openrecon } : {}),
			});
		}
	}
	if (!entries.size) throw new Error('apps.json lists no visible applications');
	return [...entries.values()].sort((a, b) => a.application.localeCompare(b.application));
}

/** Newest build per application, as shown first on its browser card. */
export function latestReleases(entries: AppListEntry[]): Map<string, AppListEntry> {
	const latest = new Map<string, AppListEntry>();
	for (const entry of entries) {
		const current = latest.get(entry.name);
		if (!current || entry.build_date > current.build_date) latest.set(entry.name, entry);
	}
	return latest;
}

let cached: Promise<AppListEntry[]> | undefined;

/** Fetches the feed once per build and shares the result across pages. */
export function loadAppList(): Promise<AppListEntry[]> {
	cached ??= (async () => {
		const response = await fetch(APPS_JSON_URL);
		if (!response.ok) throw new Error(`Failed to fetch ${APPS_JSON_URL}: HTTP ${response.status}`);
		return toAppList(parseAppsFeed(await response.json()));
	})();
	return cached;
}
